import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-1-label';

  const imageUrl = '/prism-mock/home/nodes/floating-accent.png';
  const map = ctx.textureLoader(imageUrl);
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
    map.wrapS = THREE.ClampToEdgeWrapping;
    map.wrapT = THREE.ClampToEdgeWrapping;
  }

  // atlas region 0,0,512,320 within a presumed 512x512 atlas (fallback aspect from rect)
  const atlasW = 512, atlasH = 512;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const uOffset = rect.x / atlasW;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasH;
  const uScale = rect.w / atlasW;
  const vScale = rect.h / atlasH;

  const aspect = rect.w / rect.h;
  const planeHeight = 0.9;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const uvOffsetNode = uniform(vec2(uOffset, vOffset));
  const uvScaleNode = uniform(vec2(uScale, vScale));
  const atlasUv = uv().mul(uvScaleNode).add(uvOffsetNode);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  if (map) {
    material.map = map;
    material.mapNode = texture(map, atlasUv);
  }
  material.depthWrite = false;

  const sprite = new THREE.Mesh(geometry, material);
  sprite.name = 'collection-card-1-sprite';
  group.add(sprite);

  // Text content: "Collection 1" headline
  let textMesh = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Collection 1',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: config?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    if (textMesh) {
      textMesh.position.set(0, -planeHeight / 2 - 0.15, 0.01);
      group.add(textMesh);
    }
  }

  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  // billboard toward camera each frame via onBeforeRender
  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  return group;
}
